python3 -I - <<'EOF'
import csv, collections, datetime
rows = list(csv.DictReader(open('dataset/temperature_logs.csv')))
cat = {r['product_id']: r for r in csv.DictReader(open('dataset/product_catalog.csv'))}
safe = {}
for r in cat.values():
    safe[r['storage_category'].lower()] = float(r['max_safe_temp_c'])
print("safe limits:", safe)
byz = collections.defaultdict(list)
for r in rows:
    byz[r['zone'].lower()].append((r['timestamp'], float(r['temperature_c'].replace(',', '.'))))
for z, v in byz.items():
    v.sort()
    exc = [(t, temp) for t, temp in v if temp > safe[z]]
    print(f"\n=== {z}: {len(exc)} readings above safe {safe[z]} ===")
    for t, temp in exc: print("  ", t, temp)
# Also print context around July 17-18 for all zones
print("\n=== Context 2023-07-16 12:00 to 2023-07-19 00:00 ===")
for z, v in byz.items():
    print(z, [(t[5:16], temp) for t, temp in v if '2023-07-16 12' <= t <= '2023-07-19 00'])
EOF
